-- Espansione del catalogo Mammillaria (#120): 18 nuove specie reali del
-- genere, aggiunte per coprire l'identificazione futura delle 3 piante non
-- ancora determinate a livello di specie (voce generica "mammillaria",
-- vedi #120 discussione). Fonte: pagine RHS Plants (rhs.org.uk) salvate
-- localmente da Roberta ed elaborate offline (Claude in Chrome disconnesso
-- per limitare il consumo di contesto).
--
-- Dati comuni a (quasi) tutte: Position "Full sun", Soil Loam/Sand,
-- Moisture "Well-drained", Hardiness H2 su tutte (RHS: "tolerant of low
-- temperatures, but not surviving being frozen") → esigenze.luce "Pieno
-- sole", terreno "Drenato", resistenza_gelo "nessuna" per l'intero blocco.
-- Cultivation RHS pressoché identica su tutto il genere (substrato
-- drenante, luce filtrata intensa, irrigazione moderata in crescita,
-- quasi asciutto in inverno) → manutenzione riutilizzata dal template già
-- in uso per la voce generica "mammillaria".
--
-- giorni_germinazione non compilato per nessuna specie: RHS indica sempre
-- la temperatura di semina (19-24°C) ma mai un conteggio di giorni.
--
-- mammillaria-lauii è un'eccezione reale, non un errore: RHS descrive la
-- propagazione solo per talea di fusto/foglia, non per seme — finestra di
-- semina lasciata vuota di conseguenza. Anche il Max Spread non è fornito
-- da questa fonte per questa specie: spaziatura_cm lasciata null.
--
-- mammillaria-pringlei e mammillaria-spinosissima sono le più sviluppate
-- in altezza del blocco (fino a 40cm e 30cm), da cui la dimensione minima
-- di vaso più generosa.

insert into specie
  (nome, nome_scientifico, famiglia_botanica, descrizione, esigenze, alert, manutenzione, ciclo_colturale, vaso, ciclo_vitale, slug, fonti, stato_verifica, verificata_il, verificata_da)
values
($t$Mammillaria magnimamma$t$, $t$Mammillaria magnimamma$t$, $t$Cactaceae$t$, $t$Cactus cespitoso dai fusti globosi tozzi, ricoperti di tubercoli, spine bianche e lanugine; fiori a imbuto rosa, rossi o crema in primavera e talvolta a fine estate.$t$, $j${"luce": "Pieno sole", "acqua": "Scarsa", "terreno": "Drenato"}$j$::jsonb, ARRAY[$t$evitare assolutamente ristagni idrici$t$, $t$richiede molta luce per mantenere la forma compatta$t$, $t$fioritura possibile due volte l'anno: primavera e talvolta fine estate$t$, $t$può essere soggetta a cocciniglia, ragnetto rosso e mosca bianca da serra$t$, $t$drenaggio abbondante e terreno asciutto in inverno prevengono i marciumi$t$], $j${"irrigazione": {"primavera": "ogni 14-20 giorni", "estate": "ogni 10-14 giorni", "autunno": "ogni 20-30 giorni", "inverno": "sospesa"}, "concimazione": {"primavera": "ogni 30 giorni, con concime per cactacee", "estate": "ogni 30 giorni", "autunno": "sospesa", "inverno": "sospesa"}, "potatura": {"primavera": "nessuna", "estate": "nessuna", "autunno": "nessuna", "inverno": "nessuna"}, "npk": {"primavera": "2-7-7", "estate": "2-7-7", "autunno": null, "inverno": null}}$j$::jsonb, $j${"famiglia_botanica": "Cactaceae", "giorni_germinazione": null, "giorni_trapianto": null, "giorni_raccolta": null, "finestra_semina": ["primavera", "estate"], "finestra_trapianto": ["primavera"], "resistenza_gelo": "nessuna", "spaziatura_cm": 60, "consociazioni_favorevoli": [], "consociazioni_sfavorevoli": []}$j$::jsonb, $j${"adatta": true, "dimensione_minima_litri": 5, "rinvaso_ogni_mesi": 24, "irrigazione_fattore": 0.2}$j$::jsonb, $t$perenne$t$, $t$mammillaria-magnimamma$t$, ARRAY[$t$RHS Plants (rhs.org.uk) — Mammillaria magnimamma$t$], $t$verificato$t$, now(), $t$Roberta + Claude Code (pagine RHS salvate e lette localmente)$t$),
